/**
 * Fresh BIP-39 phrases for the web demo: 128 bits of entropy (12 words) from
 * the browser's CSPRNG (crypto.getRandomValues, via @scure/bip39), with a
 * valid checksum. Only the simulated daemon in the demo uses this. A real
 * wallet's phrase is always generated by its own daemon (waved in everyday
 * mode, lnd's aezeed in node mode), never by the app.
 */
import { generateMnemonic, validateMnemonic } from '@scure/bip39';
import { wordlist } from '@scure/bip39/wordlists/english.js';

/** 128 bits → 12 words; 256 bits → 24 words (BIP-39). */
export type MnemonicStrength = 128 | 256;

export function freshDemoMnemonic(strength: MnemonicStrength = 128): string[] {
  const phrase = generateMnemonic(wordlist, strength);
  if (!validateMnemonic(phrase, wordlist)) throw new Error('generated an invalid BIP-39 phrase');
  return phrase.split(' ');
}
